function renderCase(resolver, testCase, expanded, width) {
  const component = toolRow(resolver, { ...testCase, expanded });
  const lines = component.render(width);
  // Finish a running row so its glyph timer stops.
  if (!testCase.result) component.updateResult(textResult(""), false);
  return lines;
}

function assertFixture(filename, actual) {
  const fixturePath = path.join(fixtureDir, filename);
  if (UPDATE_FIXTURES || !existsSync(fixturePath)) {
    mkdirSync(fixtureDir, { recursive: true });
    writeFileSync(fixturePath, actual);
    return;
  }
  assert.equal(actual, readFileSync(fixturePath, "utf8"), `fixture ${filename} drift; rerun with PI_MMR_UPDATE_FIXTURES=1 to refresh`);
}

describe("ampi-tui tool rows", () => {
  before(() => withHyperlinks(false));
  afterEach(() => withHyperlinks(false));
  after(() => setCapabilities(originalCapabilities));

  for (const width of [80, 140]) {
    it(`renders collapsed rows and expanded cards at ${width} columns`, async () => {
      const { createToolRendererResolver } = await load();
      const resolver = createToolRendererResolver({ home: HOME });
      const sections = [];
      for (const testCase of CASES) {
        for (const expanded of [false, true]) {
          const lines = renderCase(resolver, testCase, expanded, width);
          for (const line of lines) {
            assert.ok(stripAnsi(line).length <= width, `${testCase.name}: line wider than ${width}: ${JSON.stringify(stripAnsi(line))}`);
            assert.doesNotMatch(line, /\u001b\[(?:[0-9;]*;)?(?:4[0-9]|10[0-7]|48;)/, `${testCase.name}: background colour`);
          }
          sections.push(`=== ${testCase.name} · ${expanded ? "expanded" : "collapsed"} ===`, ...lines.map(stripAnsi));
        }
      }
      assertFixture(`rows-${width}.txt`, `${sections.join("\n")}\n`);
    });
  }

  it("draws one line per collapsed call with the status glyph first", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const row = (testCase) => renderCase(resolver, testCase, false, 140).map(stripAnsi);
    const byName = Object.fromEntries(CASES.map((c) => [c.name, c]));
    assert.deepEqual(row(byName["read success"]), ["", " ✓ Read src/index.ts L1-120"]);
    assert.deepEqual(row(byName["bash success"]), ["", " ✓ Ran npm test"]);
    assert.deepEqual(row(byName["bash error"]), ["", " ✗ Ran npm test -- --grep 'tool rows' (exit code: 1)"]);
    assert.deepEqual(row(byName["grep cancelled"]), ["", ' ⊘ Grep "foo"']);
    assert.deepEqual(row(byName["bash running"]), ["", " ⠋ Running npm run build"]);
    assert.deepEqual(row(byName["bash timed out"]), ["", " ✗ Ran sleep 3 (timed out after 1s)"]);
    assert.deepEqual(row(byName["edit with diff"]), ["", " ✓ Edited src/retry.ts +2 -1"]);
    assert.deepEqual(row(byName["shell_command left running"]), ["", " ✓ Ran npm run dev (still running as pid 4242)"]);
    assert.deepEqual(row(byName["shell_command_status still running"]), ["", " ✓ Checked pid 4242, still running"]);
    assert.deepEqual(row(byName["shell_command_kill"]), ["", " ✓ Stopped pid 4242 (SIGTERM)"]);
    assert.deepEqual(row(byName["painter running"]), ["", " ⠋ Painting A lighthouse icon, flat style …"]);
    assert.deepEqual(row(byName["painter saved"]), ["", " ✓ Painted icon.png"]);
    assert.deepEqual(row(byName["painter error"]), ["", " ✗ Painted A lighthouse icon"]);
  });

  it("cuts long rows to the width with an ellipsis", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const longCommand = CASES.find((c) => c.name === "bash long command");
    const [, line] = renderCase(resolver, longCommand, false, 80).map(stripAnsi);
    assert.equal(line.length, 80);
    assert.ok(line.endsWith("…"));
  });

  it("colours glyphs, diff lines and the failed exit code with theme roles", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const theme = {
      fg: (color, text) => `<${color}>${text}</${color}>`,
      bold: (text) => `<b>${text}</b>`,
      italic: (text) => `<i>${text}</i>`,
      underline: (text) => `<u>${text}</u>`,
      strikethrough: (text) => `<s>${text}</s>`,
    };
    const draw = (tool, args, { result, isError = false, isPartial = false, expanded = false } = {}) => {
      const renderers = resolver(tool, () => undefined);
      const context = { args, toolCallId: "c1", invalidate() {}, state: {}, cwd: CWD, executionStarted: false, argsComplete: true, isPartial, expanded, showImages: false, isError, outputPad: 1 };
      // Like Pi, draw the row once before execution starts, so it is live.
      renderers.renderCall(args, theme, context);
      context.executionStarted = true;
      const call = renderers.renderCall(args, theme, context);
      const body = result ? renderers.renderResult(result, { expanded, isPartial }, theme, context) : undefined;
      context.invalidate = () => {};
      const lines = [...call.render(200), ...(body ? body.render(200) : [])];
      if (isPartial) renderers.renderCall(args, theme, { ...context, isPartial: false });
      return lines.join("\n");
    };
    assert.match(draw("ls", {}, { result: textResult("a") }), /^ <success>✓<\/success> /);
    assert.match(draw("ls", {}, { result: textResult("boom"), isError: true }), /^ <error>✗<\/error> /);
    assert.match(draw("ls", {}, { result: textResult("Operation aborted"), isError: true }), /^ <warning>⊘<\/warning> /);
    assert.match(draw("ls", {}, { isPartial: true }), /^ <accent>⠋<\/accent> <toolTitle>Listing<\/toolTitle>/);
    const failed = draw("bash", { command: "npm test" }, { result: textResult("x\n\nCommand exited with code 2"), isError: true, expanded: true });
    assert.match(failed, /<b><error>\$<\/error><\/b> <b>npm<\/b> test/);
    assert.match(failed, /<i> \(exit code: <error>2<\/error>\)<\/i>/);
    const edit = draw("edit", { path: "a.ts", edits: [] }, { result: textResult("ok", { diff: editDiff }), expanded: true });
    assert.match(edit, /<toolDiffAdded>\+  const retries = 3;<\/toolDiffAdded>/);
    assert.match(edit, /<toolDiffRemoved>-  const retries = 1;<\/toolDiffRemoved>/);
    assert.match(edit, /<muted>2<\/muted> <toolDiffRemoved>/);
  });

  it("links the edited path with an OSC 8 file URL when the terminal supports links", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    withHyperlinks(true);
    const read = CASES.find((c) => c.name === "read success");
    const [, line] = toolRow(resolver, { ...read, expanded: true }).render(140);
    assert.ok(line.includes(`\u001b]8;;file://${CWD}/src/index.ts#L1-L120`), JSON.stringify(line));
    const collapsed = toolRow(resolver, { ...read, expanded: false }).render(140).join("\n");
    assert.ok(!collapsed.includes("\u001b]8;"), "collapsed rows carry no link");
  });

  it("animates the running glyph on a timer and stops it once the call finished", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    mock.timers.enable({ apis: ["setInterval"] });
    try {
      const component = toolRow(resolver, { tool: "bash", args: { command: "sleep 5" } });
      assert.equal(stripAnsi(component.render(80)[1]), " ⠋ Running sleep 5");
      mock.timers.tick(199);
      assert.equal(stripAnsi(component.render(80)[1]), " ⠋ Running sleep 5", "one step per 200 ms");
      mock.timers.tick(1);
      // ⠋ is dots 1, 2 and 4; dot 5 has exactly those three as neighbours and comes alive: ⠛.
      assert.equal(stripAnsi(component.render(80)[1]), " ⠛ Running sleep 5");
      component.updateResult({ ...textResult(""), isError: false }, false);
      assert.equal(stripAnsi(component.render(80)[1]), " ✓ Ran sleep 5");
      mock.timers.tick(800);
      assert.equal(stripAnsi(component.render(80)[1]), " ✓ Ran sleep 5");
    } finally {
      mock.timers.reset();
    }
  });

  it("keeps the running glyph still and starts no timer when NO_ANIMATION is set", async (t) => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    setNoAnimation(t);
    const startTimer = t.mock.method(globalThis, "setInterval");
    const component = toolRow(resolver, { tool: "bash", args: { command: "sleep 5" } });
    assert.equal(stripAnsi(component.render(80)[1]), " ⠋ Running sleep 5");
    assert.equal(startTimer.mock.callCount(), 0);
  });

  it("keeps a resumed call that never finished still", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    mock.timers.enable({ apis: ["setInterval"] });
    try {
      // A resumed session draws the call without starting its execution, and no result follows.
      const renderers = resolver("bash", () => undefined);
      const component = new ToolExecutionComponent("bash", "orphan", { command: "sleep 30" }, { showImages: false }, { name: "bash", ...renderers }, noopTui, CWD);
      const before = component.render(80).map(stripAnsi);
      mock.timers.tick(240);
      assert.deepEqual(component.render(80).map(stripAnsi), before);
    } finally {
      mock.timers.reset();
    }
  });

  it("draws a call rendered once, as in an HTML export, with its final status and no timer", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    mock.timers.enable({ apis: ["setInterval"] });
    try {
      const renderers = resolver("grep", () => undefined);
      const args = { pattern: "retries", path: "src" };
      let invalidations = 0;
      const state = {};
      const context = (expanded, isPartial, isError) => ({
        args,
        toolCallId: "export-1",
        invalidate: () => invalidations++,
        state,
        cwd: CWD,
        executionStarted: true,
        argsComplete: true,
        isPartial,
        expanded,
        showImages: false,
        isError,
        outputPad: 1,
      });
      // The export draws the call before it knows the result, then the result collapsed and expanded.
      const call = renderers.renderCall(args, plainTheme, context(false, true, false)).render(100);
      const result = textResult("src/retry.ts:2:const retries = 3;");
      const collapsed = renderers.renderResult(result, { expanded: false, isPartial: false }, plainTheme, context(false, false, false));
      const expanded = renderers.renderResult(result, { expanded: true, isPartial: false }, plainTheme, context(true, false, false));
      assert.deepEqual(call, []);
      assert.deepEqual(collapsed.render(100).map(stripAnsi), [' ✓ Grep src "retries"']);
      assert.deepEqual(expanded.render(100).map(stripAnsi), [' ✓ Grep src "retries"', "   src/retry.ts:2:const retries = 3;"]);
      mock.timers.tick(800);
      assert.equal(invalidations, 0);
    } finally {
      mock.timers.reset();
    }
  });

  it("builds a row's lines once per width", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const renderers = resolver("bash", () => undefined);
    const context = { args: { command: "ls" }, toolCallId: "c1", invalidate() {}, state: {}, cwd: CWD, executionStarted: false, argsComplete: true, isPartial: false, expanded: true, showImages: false, isError: false, outputPad: 1 };
    const header = renderers.renderCall(context.args, plainTheme, context);
    const lines = header.render(140);
    assert.equal(header.render(140), lines, "same width reuses the built lines");
    assert.notEqual(header.render(80), lines, "a new width builds them again");
  });

  it("relies on Pi drawing a new row before its execution starts", () => {
    // Rows first drawn with execution already started are treated as never redrawn (HTML export).
    const seen = [];
    const probe = { name: "probe", renderCall: (_args, _theme, context) => (seen.push(context.executionStarted), { render: () => [], invalidate() {} }) };
    const component = new ToolExecutionComponent("probe", "p1", {}, { showImages: false }, probe, noopTui, CWD);
    component.markExecutionStarted();
    assert.deepEqual(seen, [false, true]);
  });

  it("keeps a tool's own card when expanded and draws only the one-line row when collapsed", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const own = {
      renderCall: () => ({ render: () => ["own call"], invalidate() {} }),
      renderResult: () => ({ render: () => ["own result"], invalidate() {} }),
    };
    const list = { tool: "task_list", args: { tasks: [{}, {}] }, result: textResult("Updated."), next: own };
    assert.deepEqual(toolRow(resolver, { ...list, expanded: false }).render(80).map(stripAnsi), [
      "",
      " ✓ Updated task list · 2 items",
    ]);
    assert.deepEqual(toolRow(resolver, { ...list, expanded: true }).render(80), ["", "own call", "own result"]);
    // Pi's built-in renderers never replace ampi's cards for its built-in tools.
    let asked = false;
    resolver("bash", () => {
      asked = true;
      return own;
    });
    assert.equal(asked, false);
  });

  it("hands ampi-workers' tools their own renderers, collapsed and expanded", async () => {
    const { createToolRendererResolver } = await load();
    const resolver = createToolRendererResolver({ home: HOME });
    const own = {
      renderShell: "self",
      renderCall: () => ({ render: () => ["own call"], invalidate() {} }),
      renderResult: () => ({ render: () => ["own result"], invalidate() {} }),
    };
    for (const tool of ["oracle", "Task", "task_poll", "sa__security_audit"]) {
      assert.equal(resolver(tool, () => own), own, tool);
      const row = { tool, args: { task: "Review the plan" }, result: textResult("Looks good."), next: own };
      assert.deepEqual(toolRow(resolver, { ...row, expanded: false }).render(80), ["", "own call", "own result"], tool);
    }
    // Without renderers of its own (its extension is not loaded), a worker call still gets a row.
    assert.deepEqual(toolRow(resolver, { tool: "oracle", args: { task: "Review the plan" }, result: textResult("Looks good.") }).render(80).map(stripAnsi), [
      "",
      " ✓ Ran oracle · Review the plan",
    ]);
  });
});

describe("ampi-tui tool renderer registration", () => {
  it("registers one resolver when enabled and none when disabled", async () => {
    const { createMmrTuiExtension } = await importSource("extensions/ampi-tui/index.ts");
    const enabled = createMockPi();
    createMmrTuiExtension({ loadSettings: () => ({ enabled: true, intro: false }) })(enabled.pi);
    assert.equal(enabled.toolRenderers.length, 1);
    const renderers = enabled.toolRenderers[0]("read", () => undefined);
    assert.equal(renderers.renderShell, "self");
    const disabled = createMockPi();
    createMmrTuiExtension({ loadSettings: () => ({ enabled: false }) })(disabled.pi);
    assert.equal(disabled.toolRenderers.length, 0);
  });
});
